CREATE TABLE IF NOT EXISTS platforms (id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS channels (id TEXT PRIMARY KEY, platform_id TEXT NOT NULL REFERENCES platforms(id), encrypted_key TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL DEFAULT 1, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS channels_platform ON channels(platform_id);
CREATE TABLE IF NOT EXISTS models (id TEXT PRIMARY KEY, channel_id TEXT NOT NULL REFERENCES channels(id), upstream_id TEXT NOT NULL, data TEXT NOT NULL, UNIQUE(channel_id, upstream_id));
CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY CHECK(id=1), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS templates (id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admins (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, admin_id TEXT NOT NULL REFERENCES admins(id) ON DELETE CASCADE, csrf_token TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS schedules (id TEXT PRIMARY KEY, model_id TEXT NOT NULL REFERENCES models(id), kind TEXT NOT NULL, template_id TEXT NOT NULL DEFAULT '', interval_seconds INTEGER NOT NULL, next_run_at TEXT NOT NULL, enabled INTEGER NOT NULL, data TEXT NOT NULL, UNIQUE(model_id,kind,template_id));
CREATE INDEX IF NOT EXISTS schedules_due ON schedules(enabled,next_run_at);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, schedule_id TEXT, model_id TEXT NOT NULL REFERENCES models(id), channel_id TEXT NOT NULL REFERENCES channels(id), kind TEXT NOT NULL, state TEXT NOT NULL, owner TEXT NOT NULL DEFAULT '', lease_token TEXT NOT NULL DEFAULT '', lease_until TEXT, deadline TEXT, scheduled_at TEXT NOT NULL, created_at TEXT NOT NULL, finished_at TEXT, cancel_requested INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL, UNIQUE(schedule_id,scheduled_at));
CREATE INDEX IF NOT EXISTS jobs_claim ON jobs(state,kind,created_at);
CREATE INDEX IF NOT EXISTS jobs_busy ON jobs(model_id,kind,state,deadline);
CREATE INDEX IF NOT EXISTS jobs_channel_active ON jobs(channel_id,state);
CREATE INDEX IF NOT EXISTS jobs_schedule_active ON jobs(schedule_id,state);
CREATE INDEX IF NOT EXISTS jobs_artifact_latest ON jobs(kind,model_id,json_extract(data,'$.template_id'),created_at DESC,id DESC);
CREATE INDEX IF NOT EXISTS jobs_channel_artifact_latest ON jobs(kind,channel_id,json_extract(data,'$.template_id'),created_at DESC,id DESC);
CREATE UNIQUE INDEX IF NOT EXISTS jobs_one_active ON jobs(model_id,kind) WHERE state IN ('queued','claimed','dispatching');
CREATE TABLE IF NOT EXISTS probe_results (id TEXT PRIMARY KEY, job_id TEXT NOT NULL UNIQUE, model_id TEXT NOT NULL REFERENCES models(id), created_at TEXT NOT NULL, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS probe_results_model_time ON probe_results(model_id,created_at);
CREATE INDEX IF NOT EXISTS probe_results_time ON probe_results(created_at);
CREATE TABLE IF NOT EXISTS artifacts (id TEXT PRIMARY KEY, job_id TEXT NOT NULL UNIQUE, model_id TEXT NOT NULL REFERENCES models(id), template_id TEXT NOT NULL, created_at TEXT NOT NULL, hidden INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS artifacts_model_template ON artifacts(model_id,template_id,created_at DESC);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, created_at TEXT NOT NULL, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS audit_time ON audit_events(created_at);
CREATE TABLE IF NOT EXISTS worker_lease (id INTEGER PRIMARY KEY CHECK(id=1), owner TEXT NOT NULL, heartbeat_at TEXT NOT NULL, lease_until TEXT NOT NULL);
